// Part: room: Clock room (parts/room-10.mjs). Interior of the clock tower shaft, inside the box x19..21, y11..30, z11..13.
// The ladder at x21 z13 is the way in and up (the shell builds it). Focal piece: the clock works of dark oak, chain and
// trapdoors on the back of the north clock face (z11, y28..30), lit by a lantern on a chain below the belfry floor.
// Floor furniture is a clerk's desk in the west corner (lectern, chair, reader's spot) and a barrel with a candle in the
// east corner. A chain-hung lantern at the floor's edge lights the lane. Everything is drawn as text and placed by layers().
import { layers } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";

const ORIGIN = [19, 11, 11]; // the room's first interior cell: x19, y11, z11 (rows along +z, columns along +x)
const FLOOR_Y = 11;
const CEIL_Y = 30;

// One 3 x 3 layer per y (rows z11..z13, columns x19..x21). Characters not in the legend stay as they are.
const legend = {
  L: ["lectern", { facing: "east", has_book: "false" }], // the clerk's desk, read from the east
  C: ["dark_oak_stairs", { facing: "south", half: "bottom" }], // the chair, its back to the south
  B: ["barrel", { facing: "up", open: "false" }], // spare parts and oil
  c: ["candle", { candles: "3", lit: "true" }], // on the barrel, the room's first light
  G: ["dark_oak_log", { axis: "z" }], // axles at the corners of the works
  T: ["dark_oak_trapdoor", { facing: "south", half: "bottom", open: "true" }], // escapement plates, against the face
  I: ["iron_chain", { axis: "z" }], // the linkage between the plates
  P: "dark_oak_planks", // the backboard hub of the works
  K: ["iron_chain", { axis: "y" }], // the chains that hang the lanterns
  a: ["lantern", { hanging: "true" }], // the lane lantern at the floor's edge
  A: ["lantern", { hanging: "true" }], // the lantern that lights the works
};

// Build the stack of layers from FLOOR_Y to CEIL_Y as text.
const rows = [];
for (let y = FLOOR_Y; y <= CEIL_Y; y++) rows.push(["...", "...", "..."]);
const at = (y) => rows[y - FLOOR_Y];

// Floor furniture (y11): desk in the west, barrel in the east corner.
at(11)[0] = "L.B"; // z11: lectern at x19, reader's spot at x20, barrel at x21
at(11)[1] = "C.."; // z12: chair at x19; x20 and x21 are the lane
// Candle on the barrel at y12.
at(12)[0] = "..c";

// The lane lantern, hung on a chain from the belfry floor down to y13 at x19 z13.
for (let y = 14; y <= CEIL_Y; y++) at(y)[2] = "K..";
at(13)[2] = "a..";

// The clock works behind the north face (z11), y28..30, with the pendulum chain and lantern at x20 z12.
at(27)[1] = ".A.";
at(28)[0] = "GTG";
at(28)[1] = ".K.";
at(29)[0] = "IPI";
at(29)[1] = ".K.";
at(30)[0] = "GTG";
at(30)[1] = ".K.";

export function build(g) {
  layers(g, ORIGIN, legend, rows);
}

// Part: room: Belfry (parts/room-11.mjs). Interior designer's build of the belfry box x19..21, y32..34, z11..13.
// The bell (x20 y34 z12, hung from the y35 beam) is the focal piece and belongs to the dressings part; the ladder
// comes up through x21 z13 and stays clear. The room is bare, so the furniture is one ringer's bench, one barrel for
// the bell ropes, and two lanterns for light. Drawn with layers(): rows run along +x from x19, successive rows along +z.
import { layers } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";

const LEGEND = {
  s: ["dark_oak_stairs", { facing: "west", half: "bottom" }], // ringer's bench: full back on the west wall, seat faces east
  b: "barrel", // bell ropes, against the floor in the south-west corner
  L: ["lantern", { hanging: "false" }], // standing on the barrel
  H: ["lantern", { hanging: "true" }], // hung from the y35 ceiling
};

export function build(g) {
  // floor layer y32: bench on the west side, barrel in the south-west corner; x21 z13 is the ladder and stays blank
  layers(g, [19, 32, 11], LEGEND, [
    ["s..", "...", "b  "],
  ]);
  // y33: standing lantern on the barrel
  layers(g, [19, 33, 11], LEGEND, [
    ["   ", "   ", "L  "],
  ]);
  // y34: hanging lantern from the end of the y35 bell beam (x19 z12), beside the bell at x20 z12
  layers(g, [19, 34, 11], LEGEND, [
    ["   ", "H  ", "   "],
  ]);
}

// Part: room: Committee room west (parts/room-8.mjs). Interior of the box x5..17, y11..15, z11..13 (floor y10, ceiling y16).
// Plan: a long dark-oak table along z12 (x7..12) with a lectern at its head, six chairs down its south side (z13), a
// town map board on the north wall above the table as the focal piece, bookshelves in the east corner, a barrel in the
// west corner. The z11 row is the walking lane from the doorway (x15 z14) to the west end and stays clear.
// Light: two hanging lanterns under the ceiling, one centred over the table (the focal piece), one at the doorway.
import { layers, B } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";

const legend = {
  R: ["red_carpet", {}],                       // runner under the lane
  F: B.fence("dark_oak"),                      // table legs
  S: B.slab("dark_oak", "bottom"),             // table tops
  C: B.stairs("dark_oak", "south", "bottom"),  // chairs, back to the south wall
  L: ["lectern", { facing: "east" }],          // the chairman's lectern at the table head
  B: ["bookshelf", {}],
  X: ["chiseled_bookshelf", { facing: "west" }],
  K: ["barrel", { facing: "up", open: "false" }],
  Z: B.lantern(true),                          // hanging lantern
};

export function build(g) {
  // y11 (floor level) and y12 (table tops, shelves), rows z11, z12, z13 along x5..x17
  layers(g, [5, 11, 11], legend, [
    [
      "..RRRRRR.....",
      ".LFFFFFF....B",
      "K.CCCCCC....X",
    ],
    [
      ".............",
      "..SSSSSS....B",
      "............B",
    ],
  ]);

  // y15: the hanging lanterns, under the ceiling at y16
  layers(g, [5, 15, 11], legend, [
    [
      ".............",
      ".Z...Z..Z..Z.",
      ".............",
    ],
  ]);

  // The map board: a wall sign on the north wall (z10) above the table, pointing into the room
  g.set(10, 13, 11, ...B.sign("dark_oak", ["TOWN", "MAP"], { facing: "south" }));
}

// Part: room: Clerk's office (parts/room-5.mjs). The working office, box x5..9 z11..25 (floor y4), entered by the door at
// x10 z16 from the hall (the shell opens it there; plan.md says z20, the shell wins). The fireplace is on the west stack
// at x6 z17..18 (the chimney part builds the firebox); the chimney cells stay blank here.
//
// Layout: the clerk's desk is the focal piece (x7 z12..14), its chair facing the door. Filing bookshelves run along the
// north and east walls, barrels as drawers on the west wall, a red rug on the south floor, a lectern at the south end.
// Light: a lantern and a lit candle on the desk, a lantern on a barrel, a lantern on a post at the south-east corner.
// Lanes: the door cell x9 z16 and the x7..9 band stay clear.
import { layers } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";

const legend = {
  "B": "bookshelf", // filing shelves
  "f": ["dark_oak_fence", {}], // desk posts and the lamp post
  "S": ["dark_oak_slab", { type: "bottom" }], // desk top
  "h": ["dark_oak_stairs", { facing: "east", half: "bottom" }], // clerk's chair, back to the east, facing the desk
  "k": ["barrel", { facing: "up" }], // filing drawers
  "p": "flower_pot", // on the shelves
  "r": "red_carpet", // rug
  "l": ["lectern", { facing: "east", has_book: "true" }], // reading stand at the south end
  "L": ["lantern", { hanging: "false" }], // standing lanterns on a block
  "c": ["candle", { candles: "2", lit: "true" }], // desk candle
};

export function build(g) {
  const origin = [5, 4, 11];
  // Rows run along +x (x5..x9), successive rows along +z (z11..z25). ' ' = the chimney, left alone.
  // y4: floor-level furniture
  const floor = [
    "BBBBB", // z11 filing along the north wall
    "..fBB", // z12 desk post at x7; shelf at x8 and the east wall
    "...hB", // z13 chair at x8, facing the desk
    "..f..", // z14 desk post at x7
    ".....", // z15
    ".....", // z16 the door lane, kept clear
    "  ...", // z17 the fireplace front (chimney cells at x5..6)
    "  ...", // z18
    "k....", // z19 barrel drawers on the west wall
    "k....", // z20
    "k.rr.", // z21 barrel; the rug starts
    "..rr.", // z22
    "..rr.", // z23
    "..l.f", // z24 lectern at x7; lamp post at x9
    ".....", // z25
  ];
  // y5: the desk top, shelf pots, a lantern on the barrel and one on the post
  const top = [
    ".p.p.", // z11 pots on two shelves
    "..S..", // z12 desk top
    "..S.L", // z13 desk top; a lantern on the east shelf lights the fire end of the room
    "..S..", // z14 desk top
    ".....", // z15
    ".....", // z16
    ".....", // z17
    ".....", // z18
    ".....", // z19
    ".....", // z20
    "L....", // z21 lantern on the barrel
    ".....", // z22
    ".....", // z23
    "....L", // z24 lantern on the lamp post
    ".....", // z25
  ];
  // y6: things standing on the desk top
  const high = [
    ".....", // z11
    "..c..", // z12 candle
    "..L..", // z13 lantern
    ".....", // z14
    ".....", ".....", ".....", ".....", ".....", ".....", ".....", ".....", ".....", ".....", ".....", // z15..z25
  ];
  return layers(g, origin, legend, [floor, top, high]);
}

