3	// the room; a horseshoe of council tables (fence posts with slab tops) is open to the dais, with a chair on each side; public
4	// benches run down the east and west ends; a red runner crosses the centre aisle. Light: chandeliers on iron chains, a
5	// lattice 5 apart, lanterns at y13 (light 13 at the feet, so every floor cell is 8 or more), plus two standing lanterns on the dais.
6	import { layers, B } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";
